/* ---------- Account table ---------- */
.atb{overflow:hidden}
.atb-h{display:flex;align-items:center;gap:8px;padding:10px;flex-wrap:wrap;border-bottom:1px solid var(--line)}
.atb-s{display:flex;align-items:center;gap:8px;height:32px;padding:0 10px;border-radius:10px;background:var(--chip);box-shadow:inset 0 0 0 1px var(--field-line);color:var(--muted);flex:1;min-width:160px}
.atb-s input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--fg)}
.atb-s:focus-within{box-shadow:inset 0 0 0 2px var(--focus)}
.atb-s input::placeholder{color:var(--muted)}
.atb-fl{display:flex;gap:4px;flex-wrap:wrap}
.atb-fl .chip.on{background:var(--ink);color:var(--on-ink);box-shadow:none}
.atb-sc{overflow-x:auto}
.atb table{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.atb th{text-align:left;font-weight:500;font-size:12px;color:var(--muted);padding:9px 12px;white-space:nowrap}
.atb th.r,.atb td.r{text-align:right}
.atb td{padding:9px 12px;border-top:1px solid var(--line);white-space:nowrap}
.atb tr.row{cursor:pointer;transition:background .2s}
@media (hover:hover) and (pointer:fine){.atb tr.row:hover{background:var(--row)}}
/* a row that takes the focus fills the scrolling table, which would cut an outside ring: its ring is drawn inside */
.atb tr.row:focus-visible{outline-offset:-2px}
.atb tr.row.open{background:var(--wash)}
.atb .nm{display:flex;align-items:center;gap:9px;font-weight:500}
/* brand tiles sit a shade darker than the brand colour, so their white letter reads at 4.5:1 or more */
.atb .lg{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;font-size:10px;font-weight:500;color:#fff;background-image:linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3))}
.atb .hb{display:flex;align-items:center;gap:8px}
.atb .hb i{width:54px;height:5px;border-radius:3px;background:var(--line);overflow:hidden;display:block}
.atb .hb i b{display:block;height:100%;border-radius:3px}
.atb .hb span{font-size:12px;color:var(--fg2)}
.atb tr.det td{padding:0;border-top:0}
.atb-note{display:flex;align-items:center;gap:10px;padding:10px 12px 12px 45px;font-size:12.5px;color:var(--fg2);white-space:normal}
.atb-note>svg{color:var(--accent-fg,var(--accent));flex:none}
.atb-note span{flex:1}
.atb-empty td{text-align:center;color:var(--muted);padding:24px}

DM.def('account-table', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search','xs'));
  const A = [
    ['Northwind','#2f6fde','Enterprise',120,92,'$14,400','Expanding. Design team added 18 seats this month.'],
    ['Lumen Labs','#7a4ce0','Pro',14,48,'$672','Usage fell 40% after their lead designer left. Worth a check in.'],
    ['Fable & Co','#0f9a6e','Team',32,81,'$1,920','Steady. Asked about the Figma sync twice.'],
    ['Orbit','#e2681c','Pro',8,67,'$384','Trial of the agent ends Friday. 3 runs so far.'],
    ['Kite Health','#d03a5f','Enterprise',64,88,'$7,680','Renewal in 6 weeks, champion is happy.'],
    ['Paper Plane','#3c8d9e','Team',21,34,'$1,260','Two failed payments. Billing contact bounced.']
  ];
  const tb = $('tbody', r), q = $('.atb-s input', r); let plan = '', open = null;
  const hc = h => h >= 80 ? 'var(--ok)' : h >= 60 ? 'var(--warn)' : 'var(--bad)';
  function paint(anim){
    const s = q.value.trim().toLowerCase(), rows = A.filter(a => (!plan || a[2] === plan) && (!s || a[0].toLowerCase().includes(s)));
    tb.innerHTML = rows.length ? rows.map(a => `<tr class="row${open === a[0] ? ' open' : ''}" data-n="${a[0]}"><td><span class="nm"><span class="lg" style="background-color:${a[1]}">${a[0][0]}</span>${a[0]}</span></td><td><span class="tag ${a[2] === 'Enterprise' ? 'p' : a[2] === 'Pro' ? 'b' : 't'}">${a[2]}</span></td><td class="num">${a[3]}</td><td><span class="hb"><i><b style="width:${a[4]}%;background:${hc(a[4])}"></b></i><span class="num">${a[4]}</span></span></td><td class="r num">${a[5]}</td></tr>` + (open === a[0] ? `<tr class="det"><td colspan="5"><div class="fold"><div><div class="atb-note">${I('spark','xs')}<span>${a[6]}</span><button class="pill soft sm">Draft email</button></div></div></div></td></tr>` : '')).join('') : '<tr class="atb-empty"><td colspan="5">No accounts match</td></tr>';
    if (anim) stagger($$('tr.row', tb), 35);
    $$('tr.row', tb).forEach(tr => tr.onclick = () => { open = open === tr.dataset.n ? null : tr.dataset.n; paint(); const d = $('.atb-note', tb); if (d) enter(d); });
    const dr = $('.atb-note .pill', tb); if (dr) dr.onclick = e => { e.stopPropagation(); dr.innerHTML = '<span class="spin"></span>'; c.later(800, () => { dr.innerHTML = I('check','xs') + 'Draft ready'; }); };
  }
  q.oninput = () => paint(true);
  $$('.atb-fl .chip', r).forEach(ch => ch.onclick = () => { $$('.atb-fl .chip', r).forEach(x => x.classList.toggle('on', x === ch)); plan = ch.dataset.p; paint(true); });
  paint(true);
  // the preview opens one account's note on its own, unless you take over first
  c.auto(1200, () => { if (!open){ open = 'Lumen Labs'; paint(); enter($('.atb-note', tb)); } });
});
